import os
import sys
import json
import csv
from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation

# Decision rules: for each rule_id and fact_name, the only document and field that establish it.
# document is the file name without extension; field is the CSV column header.
RULES = {
    "lca.wage_105": {
        "offered wage": ("lca_disclosure", "WAGE_RATE_OF_PAY_FROM", "amount"),
        "prevailing wage": ("lca_disclosure", "PREVAILING_WAGE", "amount"),
    },
    "lca.three_years": {
        "begin date": ("lca_disclosure", "BEGIN_DATE", "date"),
        "end date": ("lca_disclosure", "END_DATE", "date"),
    },
}


def parse_amount(val):
    """Parse a string into a Decimal, returning None if invalid."""
    try:
        # Remove thousands separators if any
        val = val.replace(",", "")
        return Decimal(val)
    except (InvalidOperation, ValueError):
        return None


def parse_date(val):
    """Parse a string into a date object.
    Handles Excel serial dates (1900 date system) and YYYY-MM-DD strings.
    """
    # Try Excel serial date
    try:
        serial = float(val)
        # Excel serial date conversion (1900 date system with leap year bug)
        base = datetime(1899, 12, 30)
        dt = base + timedelta(days=serial)
        return dt.date()
    except (ValueError, OverflowError):
        pass
    # Try ISO date string
    try:
        return datetime.strptime(val, "%Y-%m-%d").date()
    except ValueError:
        return None


def format_amount(d):
    """Format a Decimal as a decimal string without unnecessary trailing zeros."""
    s = str(d)
    if "." in s:
        s = s.rstrip("0").rstrip(".")
    return s


def get_rows(packet_dir, document, cache):
    """Read and cache CSV rows for a given document name."""
    if document not in cache:
        path = os.path.join(packet_dir, document + ".csv")
        rows = []
        if os.path.exists(path):
            with open(path, newline="", encoding="utf-8-sig") as f:
                reader = csv.DictReader(f)
                rows = list(reader)
        cache[document] = rows
    return cache[document]


def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    file_cache = {}
    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        fact_names = facts_by_rule.get(rule_id, [])
        result = {}

        for fact_name in fact_names:
            if rule_id in RULES and fact_name in RULES[rule_id]:
                document, field, fact_type = RULES[rule_id][fact_name]
                rows = get_rows(packet_dir, document, file_cache)
                values = []

                for row in rows:
                    if row.get("CASE_NUMBER") == entity:
                        val = row.get(field, "")
                        if val:
                            val = val.strip()
                        if not val:
                            continue

                        if fact_type == "amount":
                            d = parse_amount(val)
                            if d is not None:
                                values.append(d)
                        elif fact_type == "date":
                            d = parse_date(val)
                            if d is not None:
                                values.append(d)

                if not values:
                    result[fact_name] = "ABSENT"
                else:
                    first = values[0]
                    if all(v == first for v in values):
                        if fact_type == "amount":
                            s = format_amount(first)
                            result[fact_name] = [s, document]
                        elif fact_type == "date":
                            s = first.strftime("%Y-%m-%d")
                            result[fact_name] = [s, document]
                    else:
                        result[fact_name] = "CONFLICT"
            else:
                # Unknown rule or fact name
                result[fact_name] = "ABSENT"

        output[pair] = result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

