import sys
import os
import json
import csv
from datetime import date, timedelta
from decimal import Decimal

def convert_date(val):
    val = val.strip()
    if not val:
        return None
    try:
        float(val)
        base = date(1899, 12, 30)
        d = base + timedelta(days=int(float(val)))
        return d.isoformat()
    except ValueError:
        pass
    try:
        y, m, d = val.split('-')
        return f"{int(y):04d}-{int(m):02d}-{int(d):02d}"
    except:
        pass
    return val

def convert_amount(val):
    val = val.strip().replace(',', '').replace('$', '')
    if not val:
        return None
    try:
        return str(Decimal(val))
    except:
        return val

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts_map = manifest["facts"]

    csv_path = os.path.join(packet_dir, "lca_disclosure.csv")
    records = {}
    with open(csv_path, newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            case_num = row["CASE_NUMBER"].strip()
            if case_num not in records:
                records[case_num] = []
            records[case_num].append(row)

    fact_columns = {
        "lca.wage_105": {
            "offered wage": "WAGE_RATE_OF_PAY_FROM",
            "prevailing wage": "PREVAILING_WAGE"
        },
        "lca.three_years": {
            "begin date": "BEGIN_DATE",
            "end date": "END_DATE"
        }
    }

    fact_converters = {
        "lca.wage_105": {
            "offered wage": convert_amount,
            "prevailing wage": convert_amount
        },
        "lca.three_years": {
            "begin date": convert_date,
            "end date": convert_date
        }
    }

    output = {}
    for pair in pairs:
        rule_id, entity = pair.split("::")
        fact_names = facts_map[rule_id]
        output[pair] = {}
        for fact_name in fact_names:
            col = fact_columns[rule_id][fact_name]
            converter = fact_converters[rule_id][fact_name]

            values = set()
            if entity in records:
                for row in records[entity]:
                    raw_val = row.get(col, "")
                    if raw_val and raw_val.strip():
                        converted = converter(raw_val)
                        if converted is not None:
                            values.add(converted)

            if not values:
                output[pair][fact_name] = "ABSENT"
            elif len(values) > 1:
                output[pair][fact_name] = "CONFLICT"
            else:
                output[pair][fact_name] = [list(values)[0], "lca_disclosure"]

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

